.nav-tabs {
  display: flex; gap: 4px; overflow-x: auto; padding-bottom: 4px;
  scrollbar-width: none; margin-bottom: 1rem;
}
.nav-tabs::-webkit-scrollbar { display: none; }
.tab-btn {
  flex-shrink: 0;
  padding: 5px 12px;
  font-size: 12px; font-weight: 400;
  border: 0.5px solid var(--border);
  border-radius: 20px;
  background: var(--surface-2);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
}
.tab-btn:hover { border-color: var(--border-strong); color: var(--text-primary); }
.tab-btn.active {
  background: var(--text-primary); color: var(--surface-2);
  border-color: var(--text-primary);
}

.section-header {
  display: flex; align-items: center; gap: 8px;
  padding: 0.5rem 0 0.75rem;
  border-bottom: 0.5px solid var(--border);
  margin-bottom: 0.75rem;
}
.section-dot {
  width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0;
}
.section-header h2 { font-size: 15px; font-weight: 500; color: var(--text-primary); }
.section-count {
  margin-left: auto;
  font-size: 11px; color: var(--text-muted);
  background: var(--surface-1); border: 0.5px solid var(--border);
  border-radius: 20px; padding: 2px 8px;
}

